/**
 * Types for the modules Vite supplies rather than the filesystem.
 *
 * `virtual:omnihilbras-version` is generated by the `repoVersion` plugin in `vite.config.ts` and
 * carries the checkout's version, which the sidebar compares against the running gateway's. It is a
 * virtual module rather than a `define` because a `define` does not reach a dev-served source module —
 * see `src/lib/pageVersion.ts` for what that cost.
 */
declare module 'virtual:omnihilbras-version' {
  export const version: string;
}